using Microsoft.EntityFrameworkCore;
namespace Server_api.Features.Projects.Queries.GetAiTaskSuggestions;
public sealed class GetAiTaskSuggestionsEndpoint : IEndpoint
{ public void MapEndpoint(IEndpointRouteBuilder endpoints) { endpoints.MapGet("/api/ai/plan-suggestions/{suggestionId:guid}/tasks", async (Guid suggestionId, AppDbContext db, ICurrentUser currentUser, CancellationToken cancellationToken) => { var suggestion = await db.AiPlanSuggestions.Include(x => x.Project).ThenInclude(x => x.Workspace).SingleOrDefaultAsync(x => x.Id == suggestionId, cancellationToken); if (suggestion is null) return Results.NotFound(); if (suggestion.Project.Workspace.OwnerId != currentUser.UserId) return Results.Forbid(); return Results.Ok(await db.Set<AiTaskSuggestion>().AsNoTracking().Where(x => x.AiPlanSuggestionId == suggestionId).Select(x => new { x.Id, x.Title, x.Description, x.Context, x.Category, x.ApprovalStatus }).ToListAsync(cancellationToken)); }).RequireAuthorization().WithTags("AI"); } }
